@strawberry.type
class Query:
    @strawberry.field
    def invoice(self, info: Info, id: int) -> Optional[InvoiceType]:
        db: Session = info.context["db"]
        current_user = info.context["current_user"]
        record = db.query(Invoice).filter(Invoice.id == id, Invoice.user_id == current_user.id).first()
        if not record:
            return None
        return InvoiceType.from_orm(record)
